style.css:
@-moz-document domain("gemini.google.com") {
/*
   * Gemini 대화 내용이 표시되는 컨테이너입니다.
   * 기본으로 설정된 최대 너비(max-width) 값을 더 큰 값으로 덮어씁니다.
   * 148rem 대신 100%, 1200px 등 원하는 다른 값으로 수정할 수 있습니다.
  */
  .conversation-container {
    max-width: 148rem !important;
  }

  /*
   * 대화 입력창(prompt)이 있는 하단 영역입니다.
   * 이 부분의 너비도 함께 늘려주어야 자연스럽습니다.
  */
  .input-area-container,
  .input-box-container {
    max-width: 100% !important; /* 새로운 컨테이너 너비에 맞게 100%로 설정 */
  }

  /*
   * 채팅 UI 자체의 최대 너비를 조정하여 전체적인 레이아웃을 넓힙니다.
   * 이 규칙은 응답이 생성될 때의 너비도 포함합니다.
   */
  mat-sidenav-content,
  .chat-history,
  .main-view {
    max-width: none !important;
  }

  /*
   * 응답이 표시되는 부분의 너비도 조정합니다.
   */
  .model-response-text {
     max-width: 100% !important;
  }
}
